        echo '<aside class="nasa-inspector card" data-nasa-inspector hidden aria-label="Plain-English handbook explanation"><button type="button" class="btn btn-outline-secondary" data-nasa-help-close>Close explanation</button><div data-nasa-inspector-content></div></aside></div>';
    }
    private static function checks(array $ready): void
    {
        echo '<ul class="nasa-checks">';
        foreach($ready['checks'] as $c){
            echo '<li class="'.($c['passed']?'passed':'missing').'"><span aria-hidden="true">'.($c['passed']?'✓':'○').'</span><div><strong>'.self::e($c['title']).'</strong>'.($c['waived']?self::chip('Tailored','medium'):'').'<p>'.self::e($c['detail']).'</p>';
            if(isset($c['tailoring'])){$t=$c['tailoring'];echo '<details><summary>Tailored — see rationale · '.self::e($t['item_key']).' v'.(int)$t['version'].'</summary><p>'.self::e($t['rationale']).'</p><ul>';foreach($t['criteria'] as $key)echo '<li>'.self::e(NasaKnowledge::tailoringCriteria()[$key]['title']).' · §3.11.2</li>';echo '</ul><p><strong>Residual risk:</strong> '.self::e($t['residual_risk']).'</p><p><strong>Revisit:</strong> '.self::e($t['revisit']).'</p></details>';}
            echo '</div></li>';
        }echo '</ul>';
    }

    private static function recordForm(string $kind,?array $r,string $phase): void
    {
        $d=$r['data']??[];self::form('nasa_save_record',['kind'=>$kind,'item_key'=>$r['item_key']??'','version'=>$r['version']??0]);self::input('title',($kind==='tpm'?'Measure':ucfirst($kind)).' title',$r['title']??'');self::area('content',match($kind){'requirement'=>'System promise (use shall)','risk'=>'What could happen and why it matters','tpm'=>'Why this measure matters','tailoring'=>'Rationale for deferring this check',default=>'Decision and rationale'},$r['content']??'');
        if($kind==='requirement'){self::input('source','User need / source reference',$d['source']??'',1000);self::select('method','Verification method',['test'=>'Test — execute a procedure','analysis'=>'Analysis — reason from data','inspection'=>'Inspection — examine the product','demonstration'=>'Demonstration — show an outcome'],$d['method']??'test');self::area('evidence','Actual evidence / result reference',$d['evidence']??'',2000,3,false);self::select('status','Evidence state',['unverified'=>'Unverified','verified'=>'Verified — reviewed linked evidence and owner confirmation'],$r['status']??'unverified');$field='nasa-field-'.++self::$field;echo '<label for="'.$field.'"><input id="'.$field.'" type="checkbox" name="verification_confirmed" value="1"> I confirm this exact requirement and method are supported by reviewed linked evidence.</label>'; }
        elseif($kind==='risk'){self::input('owner','Response owner',$d['owner']??'Project owner');self::area('mitigation','Response, acceptance rationale and revisit trigger',$d['mitigation']??'',2000);foreach(['likelihood'=>'Initial likelihood','consequence'=>'Initial impact','residual_likelihood'=>'Remaining likelihood','residual_consequence'=>'Remaining impact'] as $key=>$name)self::select($key,$name.' (1 low to 5 high)',array_combine(range(1,5),range(1,5)),$d[$key]??3);self::input('requirement','Linked requirement ID (optional)',$d['requirement']??'',40,'text',false);self::select('artifact','Linked artifact',[''=>'None']+array_map(static fn($a)=>$a[0],NasaKnowledge::ARTIFACTS),$d['artifact']??'risks');self::select('status','Risk state',['open'=>'Open','mitigated'=>'Mitigated — response applied','accepted'=>'Accepted — rationale recorded','closed'=>'Closed'],$r['status']??'open');}
        elseif($kind==='tpm'){echo '<input type="hidden" name="status" value="recorded">';self::input('units','Units',$d['units']??'milliseconds',80);self::select('direction','Target direction',['at_most'=>'At most','at_least'=>'At least'],$d['direction']??'at_most');self::input('target','Target value',$d['target']??'',40,'number');self::input('observed','Observed value',$d['observed']??'',40,'number');self::input('method','Measurement method / date / evidence',$d['method']??'',1000);}
        elseif($kind==='decision'){self::area('alternatives','Alternatives and trade-offs',$d['alternatives']??'',2000);self::area('revisit','When to reconsider',$d['revisit']??'',1000);self::select('status','Decision state',['proposed'=>'Proposed','decided'=>'Decided by me'],$r['status']??'proposed');}
        else{echo '<input type="hidden" name="status" value="recorded">';self::select('phase','Phase for this exception',array_map(static fn($p)=>$p[0],NasaKnowledge::phases()),$d['phase']??$phase);self::select('artifact','Document / check being tailored',array_map(static fn($a)=>$a[0],NasaKnowledge::ARTIFACTS),$d['artifact']??'conops');echo '<fieldset><legend>Which NASA tailoring criteria justify this exception?</legend><p class="nasa-hint">Choose at least one. Handbook §3.11.2, adapted to software planning.</p>';foreach(NasaKnowledge::tailoringCriteria() as $key=>$criterion){$field='nasa-field-'.++self::$field;echo '<label for="'.$field.'"><input type="checkbox" id="'.$field.'" name="criteria[]" value="'.self::e($key).'"'.(in_array($key,$d['criteria']??[],true)?' checked':'').'> '.self::e($criterion['title']).'</label><p class="nasa-hint">'.self::e($criterion['short']).'</p>';}echo '</fieldset>';self::area('residual_risk','Residual risk introduced by this deferral',$d['residual_risk']??'',2000);self::area('revisit','Revisit trigger, date or condition',$d['revisit']??'',1000);}
        self::submit($r?'Save new record version':'Add '.($kind==='tpm'?'measure':$kind),'btn-primary');
        if($r){self::form('nasa_archive_record',['kind'=>$kind,'item_key'=>$r['item_key'],'version'=>$r['version']]);self::submit('Archive '.$r['item_key'],'btn-sm btn-outline-danger');}
    }
    private static function reviews(array $s,array $ready): void
    {
        $p=$s['project'];echo '<section id="nasa-reviews" data-nasa-panel="reviews"><article class="card"><div class="card-body"><h3>Readiness before the next phase</h3><a href="#nasa-collaboration" data-nasa-open="overview">Ask SE collaborator for next move →</a>';self::checks($ready);$reviewed=(bool)array_filter($s['reviews'],static fn($r)=>(int)$r['revision']===(int)$p['revision']&&$r['created_by']==='local');echo '<p>'.($reviewed?'A local review is recorded for this revision.':'Record a readiness review of the current revision before advancing.').'</p>';self::form('nasa_advance',['revision'=>$p['revision']]);self::submit('Advance to next phase','btn-primary',!$ready['ready']||!$reviewed||$p['phase']==='F');echo '<p class="nasa-hint">Address missing documents or record a proportionate exception under Decisions & tailoring. This changes planning phase only.</p></div></article>';
        foreach($s['reviews'] as $r){$report=json_decode($r['report_json'],true)?:[];$stale=(int)$r['revision']!==(int)$p['revision'];echo '<article class="card nasa-review"><div class="card-body"><h3>'.self::term($r['review_type'],$r['review_type']).' · #'.$r['id'].'</h3>'.self::chip($r['created_by']==='ai_draft'?'AI advisory draft':'Local readiness review').($stale?self::chip('Earlier project revision','medium'):'').'<p>'.self::e($report['summary']??'').'</p><h4>Strengths</h4><ul>';foreach($report['strengths']??[] as $text)echo '<li>'.self::e($text).'</li>';echo '</ul><h4>Gaps and next actions</h4>';
            foreach($report['gaps']??[] as $index=>$f){echo '<div class="nasa-finding">'.self::chip($f['severity'],$f['severity']).'<h5>'.self::e($f['title']).'</h5><p>'.self::e($f['detail']).'</p><p>'.self::term($f['artifact'],'Explain this finding').'</p><div class="nasa-package-actions">';self::form('nasa_generate',['artifact'=>$f['artifact']],true);self::submit('Draft this artifact','btn-sm btn-outline-primary',!AgentRunner::configured());self::form('nasa_task',['review_id'=>$r['id'],'finding_index'=>$index]);self::submit('Create a task','btn-sm btn-outline-primary');if($s['map_runs']){self::form('nasa_map',['review_id'=>$r['id'],'finding_index'=>$index]);$options=[];foreach($s['map_runs'] as $run)$options[$run['id']]='Investigation #'.$run['id'].' · '.$run['phase'];self::select('run_id','Linked research map',$options,$s['map_runs'][0]['id']);self::submit('Add unchecked map idea','btn-sm btn-outline-secondary');}echo '</div></div>';}
            echo '<ul>';foreach($report['next_actions']??[] as $a)echo '<li>'.self::e($a).'</li>';echo '</ul></div></article>';}
        NasaDisciplineView::baselines($s,self::$csrf);echo '<details class="card"><summary>AI request and spend history</summary><div class="card-body"><p>Uncertain calls retain their risk reservation. Saved usage is an estimate, not an invoice.</p><ul>';foreach($s['requests'] as $r)echo '<li>#'.$r['id'].' · '.self::e($r['action'].' · '.$r['status'].' · '.$r['model']).' · '.($r['estimated_usd']===null?'Cost unknown; $'.number_format((float)$r['reserved_usd'],4).' reserved':'$'.number_format((float)$r['estimated_usd'],4).' estimated').($r['error']?'<p>'.self::e($r['error']).'</p>':'').'</li>';echo '</ul></div></details></section>';
    }
    private static function helper(): void
    {
        echo '<div class="nasa-handbook"><h3>A handbook you can use without reading the book</h3><p>Original plain-English explanations and software examples, referenced to <a href="'.NasaKnowledge::SOURCE.'" target="_blank" rel="noopener noreferrer">NASA Systems Engineering Handbook, Rev 2</a>. Section numbers refer to the handbook, not PDF viewer pages.</p><label for="nasa-help-search">Find a term or process</label><input class="form-control" type="search" id="nasa-help-search" data-nasa-help-search placeholder="Try requirements, risk or verification"><h4>Design and realise, with management throughout</h4><div class="nasa-processes">';foreach(['Design','Realise','Manage'] as $group){echo '<div><h5>'.$group.'</h5>';foreach(NasaKnowledge::processes() as $ref=>$process)if($process[1]===$group)echo '<p>'.self::term('process_'.str_replace('.','_',$ref),$process[0]).'</p>';echo '</div>';}echo '</div>';
        echo '<details data-nasa-glossary><summary>Recursive practice, SEMP and maturity</summary>';foreach(NasaKnowledge::practiceNotes() as $note)echo '<h4>'.self::e($note['title']).'</h4><p>'.self::e($note['detail']).'</p><p class="nasa-hint">Handbook reference: '.self::e($note['ref']).'</p>';echo '</details>';
        foreach(NasaKnowledge::phaseCriteria() as $key=>$criteria){echo '<details data-nasa-glossary><summary>'.self::e(NasaKnowledge::phases()[$key][0]).' · entrance and success</summary><h4>Entrance</h4><ul>';foreach($criteria['entrance'] as $text)echo '<li>'.self::e($text).'</li>';echo '</ul><h4>Success</h4><ul>';foreach($criteria['success'] as $text)echo '<li>'.self::e($text).'</li>';echo '</ul><p>'.self::e($criteria['practitioner']).'</p><p class="nasa-hint">Software adaptation · Handbook reference: '.self::e($criteria['ref']).'</p></details>';}
        foreach(NasaKnowledge::processDetails() as $ref=>$process)echo '<details data-nasa-glossary><summary>§'.self::e($ref).' · '.self::e(NasaKnowledge::processes()[$ref][0]).'</summary><h4>Why this process exists</h4><p>'.self::e($process['why']).'</p><h4>Common failure mode</h4><p>'.self::e($process['failure']).'</p><p>'.self::e($process['practitioner']).'</p><p class="nasa-hint">Handbook reference: '.self::e($process['ref']).'</p></details>';
        foreach(NasaKnowledge::terms() as $key=>$term)echo '<details data-nasa-glossary><summary>'.self::e($term['title']).'</summary><div id="nasa-help-'.self::e($key).'" data-nasa-help-content="'.self::e($key).'"><h4>'.self::e($term['title']).'</h4><p>'.self::e($term['detail']).'</p><h5>A software / AI example</h5><p class="nasa-prewrap">'.self::e($term['example']).'</p><p class="nasa-hint">Handbook reference: '.self::e($term['ref']).'</p><a href="'.NasaKnowledge::SOURCE.'" target="_blank" rel="noopener noreferrer">Open the official handbook</a></div></details>';
        echo '</div>';
    }
}
